use std::fs

fn fail() {
    println("error")
    std::process::exit(1)
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let lines: Vec<string> = text.lines().collect()
    if lines.len() < 1 {
        fail()
        return
    }
    let mut hdr: Vec<int> = []
    for p in lines[0].split_whitespace() {
        match p.parse::<int>() {
            Ok(v) => hdr.push(v),
            Err(_) => {
                fail()
                return
            }
        }
    }
    if hdr.len() != 2 || hdr[0] < 1 || hdr[1] < 1 {
        fail()
        return
    }
    let r = hdr[0]
    let c = hdr[1]
    if (lines.len() as int) < r + 1 {
        fail()
        return
    }
    let mut grid: Vec<Vec<int>> = []
    let mut i = 0
    while i < r {
        let mut row: Vec<int> = []
        for p in lines[(i + 1) as usize].split_whitespace() {
            match p.parse::<int>() {
                Ok(v) => row.push(v),
                Err(_) => {
                    fail()
                    return
                }
            }
        }
        if (row.len() as int) != c {
            fail()
            return
        }
        grid.push(row)
        i += 1
    }
    let mut out: Vec<string> = []
    let mut top = 0
    let mut bot = r - 1
    let mut left = 0
    let mut right = c - 1
    while top <= bot && left <= right {
        let mut j = left
        while j <= right {
            out.push("${grid[top as usize][j as usize]}")
            j += 1
        }
        top += 1
        j = top
        while j <= bot {
            out.push("${grid[j as usize][right as usize]}")
            j += 1
        }
        right -= 1
        if top <= bot {
            j = right
            while j >= left {
                out.push("${grid[bot as usize][j as usize]}")
                j -= 1
            }
            bot -= 1
        }
        if left <= right {
            j = bot
            while j >= top {
                out.push("${grid[j as usize][left as usize]}")
                j -= 1
            }
            left += 1
        }
    }
    println(out.join(" "))
}

